parameters.jsCode:
// Uma compra parcelada vira N despesas — uma por mes, cada uma marcavel como
// paga separadamente, que e como a divida acontece na vida real. O campo Grupo
// liga todas a mesma compra, para dar para apagar o conjunto depois.
const b = $json.body || {};
const texto = (v) => String(v ?? "").trim();
const lista = (v) => texto(v) || null;
const numero = (v) => {
  const n = Number(String(v ?? "").replace(",", "."));
  return Number.isFinite(n) ? n : null;
};

const descricao = texto(b.descricao);
const valor = numero(b.valor);
if (!descricao || valor === null || valor <= 0) {
  return [{ json: { invalido: true, mensagem: "Preencha a descrição e um valor válido." } }];
}

// Soma meses sem estourar o dia: 31/01 + 1 mes vira 28/02, nao 03/03.
function somaMeses(iso, meses) {
  const [a, m, d] = String(iso).slice(0, 10).split("-").map(Number);
  const alvo = new Date(Date.UTC(a, m - 1 + meses, 1));
  const ultimoDia = new Date(Date.UTC(alvo.getUTCFullYear(), alvo.getUTCMonth() + 1, 0)).getUTCDate();
  const dia = String(Math.min(d, ultimoDia)).padStart(2, "0");
  const mes = String(alvo.getUTCMonth() + 1).padStart(2, "0");
  return alvo.getUTCFullYear() + "-" + mes + "-" + dia;
}

const parcelas = Math.max(1, Math.min(60, Number(b.parcelas) || 1));
const vencimento = lista(b.vencimento);
const fornecedorId = /^rec[A-Za-z0-9]{14}$/.test(texto(b.fornecedorId)) ? texto(b.fornecedorId) : "";
const servicoId = /^rec[A-Za-z0-9]{14}$/.test(texto(b.servicoId)) ? texto(b.servicoId) : "";
const cartaoId = /^rec[A-Za-z0-9]{14}$/.test(texto(b.cartaoId)) ? texto(b.cartaoId) : "";

// Grupo so faz sentido quando ha mais de uma parcela.
const grupo = parcelas > 1
  ? "g" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8)
  : "";

// Divide em centavos para nao perder um centavo no arredondamento: a ultima
// parcela fica com a sobra, e a soma bate exatamente com o total.
const centavosTotal = Math.round(valor * 100);
const centavosBase = Math.floor(centavosTotal / parcelas);
const sobra = centavosTotal - centavosBase * parcelas;

const registros = [];
for (let i = 1; i <= parcelas; i++) {
  const centavos = centavosBase + (i === parcelas ? sobra : 0);
  const fields = {
    Descricao: parcelas > 1 ? descricao + " (" + i + "/" + parcelas + ")" : descricao,
    Valor: centavos / 100,
    Categoria: lista(b.categoria) || "Outros",
    Forma_Pagamento: lista(b.formaPagamento),
    Observacoes: texto(b.observacoes),
    // So a primeira pode ja nascer paga; as futuras sempre pendentes.
    Status: i === 1 ? (lista(b.status) || "Pendente") : "Pendente",
  };

  if (vencimento) fields.Vencimento = somaMeses(vencimento, i - 1);
  if (parcelas > 1) {
    fields.Parcela_Numero = i;
    fields.Parcela_Total = parcelas;
    fields.Grupo = grupo;
  }
  if (fornecedorId) fields.Fornecedor_Ref = [fornecedorId];
  if (servicoId) fields.Servico_Ref = [servicoId];
  if (cartaoId) fields.Cartao_Ref = [cartaoId];
  if (i === 1 && lista(b.dataPagamento)) fields.Data_Pagamento = lista(b.dataPagamento);

  registros.push({ fields });
}

// O Airtable aceita no maximo 10 registros por chamada.
const chamadas = [];
for (let i = 0; i < registros.length; i += 10) {
  chamadas.push({
    invalido: false,
    metodo: "POST",
    url: "https://api.airtable.com/v0/appjAmWXV7Zr33UqE/tblNduEKl2jY280V0",
    corpo: { typecast: true, records: registros.slice(i, i + 10) },
  });
}

return chamadas.map((c) => ({ json: c }));

